def parse_ini_strict(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    current_section = ""
    result = {}
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        s = line.strip()
        if not s:
            continue
        if s.startswith(';') or s.startswith('#'):
            continue
        if s.startswith('[') and s.endswith(']'):
            name = s[1:-1].strip()
            if not name:
                raise ValueError("Section name is empty.")
            if '[' in name or ']' in name:
                raise ValueError("Section name contains '[' or ']'.")
            current_section = name
            if current_section not in result:
                result[current_section] = {}
            continue
        if '=' not in s:
            raise ValueError("Missing '=' in line.")
        key_part, r = s.split('=', 1)
        key = key_part.strip().lower()
        if not key:
            raise ValueError("Empty key.")
        if key in result.get(current_section, {}):
            raise ValueError("Duplicate key in section.")
        # Process value
        r = r
        # Check if quoted
        v_stripped = r.strip()
        if v_stripped.startswith('"'):
            # Quoted value
            value_str, r_remainder = parse_quoted_value(r)
            result[current_section][key] = value_str
        else:
            # Unquoted value
            value_str = parse_unquoted_value(r)
            result[current_section][key] = value_str
    return result

def parse_quoted_value(r):
    # Find closing quote, handling escapes
    i = 0
    n = len(r)
    if i >= n or r[i] != '"':
        raise ValueError("Quoted value must start with quote.")
    i += 1
    value_parts = []
    while i < n:
        if r[i] == '\\':
            i += 1
            if i >= n:
                raise ValueError("Incomplete escape sequence.")
            if r[i] in ['"', '\\', 'n']:
                if r[i] == 'n':
                    value_parts.append('\n')
                else:
                    value_parts.append(r[i])
                i += 1
            else:
                raise ValueError(f"Invalid escape sequence: \\{r[i]}.")
        elif r[i] == '"':
            i += 1
            break
        else:
            value_parts.append(r[i])
            i += 1
    if i > n:
        raise ValueError("Unclosed quote.")
    value = ''.join(value_parts)
    remainder = r[i:].strip()
    if remainder and not remainder.startswith(';') and not remainder.startswith('#'):
        raise ValueError("Text after quoted value is not a comment.")
    return value, remainder

def parse_unquoted_value(r):
    # Find the first occurrence of ; or # preceded by a blank or at start
    comment_pos = -1
    for i in range(len(r)):
        if r[i] in ';#':
            if i == 0 or r[i-1] in ' \t':
                comment_pos = i
                break
    if comment_pos != -1:
        value_part = r[:comment_pos].strip()
        return value_part
    else:
        return r.strip()
