To solve the problem of integer partitions efficiently, we use dynamic programming with memoization. The `count_partitions` function calculates the number of partitions recursively, using memoization to avoid redundant computations. The recurrence relations differ based on the `distinct` flag: for distinct partitions, each part must be unique, so the largest part is subtracted from `n` and the next parts are strictly smaller. For non-distinct partitions, the largest part can be reused. The `kth_partition` function reconstructs the k-th partition by iteratively determining each part by comparing `k` with the counts of possible partitions starting with each candidate part. Both functions handle edge cases like `n=0` and invalid inputs.

```python
import functools

def count_partitions(n, max_part=None, distinct=False):
    if n < 0:
        raise ValueError
    if max_part is not None:
        if not isinstance(max_part, int):
            raise ValueError
        if max_part < 0:
            raise ValueError
    if n == 0:
        return 1
    if max_part is None:
        m = n
    else:
        m = max_part
    if m < 1:
        return 0 if n != 0 else 1

    @functools.lru_cache(maxsize=None)
    def dp(remaining, max_p, distinct_flag):
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        if max_p < 1:
            return 0 if remaining != 0 else 1
        limit = min(max_p, remaining)
        if distinct_flag:
            return dp(remaining - limit, limit - 1, True) + dp(remaining, limit - 1, True)
        else:
            return dp(remaining - limit, limit, False) + dp(remaining, limit - 1, False)

    return dp(n, m, distinct)

def kth_partition(n, k, max_part=None, distinct=False):
    if n < 0 or k < 0:
        raise ValueError
    if max_part is not None:
        if not isinstance(max_part, int):
            raise ValueError
        if max_part < 0:
            raise ValueError
    if n == 0:
        if k != 0:
            raise ValueError
        return ()
    if max_part is None:
        m = n
    else:
        m = max_part
    if m < 1:
        raise ValueError

    @functools.lru_cache(maxsize=None)
    def count(remaining, max_p, distinct_flag):
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        if max_p < 1:
            return 0 if remaining != 0 else 1
        limit = min(max_p, remaining)
        if distinct_flag:
            return count(remaining - limit, limit - 1, True) + count(remaining, limit - 1, True)
        else:
            return count(remaining - limit, limit, False) + count(remaining, limit - 1, False)

    total = count(n, m, distinct)
    if k >= total:
        raise ValueError

    result = []
    remaining = n
    current_max = m
    while remaining > 0:
        for part in range(1, current_max + 1):
            if part > remaining:
                continue
            if distinct:
                next_max = part - 1
            else:
                next_max = part
            cnt = count(remaining - part, next_max, distinct)
            if k < cnt:
                result.append(part)
                remaining -= part
                current_max = part - 1 if distinct else part
                break
            else:
                k -= cnt
    return tuple(result)
