            raise ValueError("u or v out of range")
        if w < 1:
            raise ValueError("Weight must be >=1")
    if not isinstance(src, int) or not isinstance(dst, int):
        raise ValueError("src or dst not integer")
    if not (0 <= src < n and 0 <= dst < n):
        raise ValueError("src or dst out of range")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize Dijkstra's structures
    INF = float('inf')
    dist = [INF] * n
    count = [0] * n
    path = [[] for _ in range(n)]
    dist[src] = 0
    count[src] = 1
    path[src] = [src]

    heap = [(0, src)]

