    if not isinstance(rolls, (list, tuple)) or not all(isinstance(r, int) and 0 <= r <= 10 for r in rolls):
        raise ValueError("Invalid rolls")
    if not isinstance(partial, bool):
        raise ValueError("partial must be a boolean")

    index = 0
    frames = 10
    for frame in range(frames):
        if index >= len(rolls):
            if not partial:
                raise ValueError("Incomplete game")
            else:
                break
        if frame < 9:  # Frames 1-9
            first = rolls[index]
            if first < 0 or first > 10:
                raise ValueError("Invalid roll value")
            if first == 10:
                index += 1
            else:
                if index + 1 >= len(rolls):
                    if not partial:
                        raise ValueError("Incomplete game")
                    else:
                        break
                second = rolls[index + 1]
                if second < 0 or second > 10:
                    raise ValueError("Invalid roll value")
                if first + second > 10:
                    raise ValueError("Frame sum exceeds 10")
                index += 2
        else:  # Frame 10
            first = rolls[index]
            if first < 0 or first > 10:
                raise ValueError("Invalid roll value")
            if first == 10:
                # Need two more rolls
                if index + 3 > len(rolls):
                    if not partial:
                        raise ValueError("Incomplete game")
                    else:
                        # Take as many as possible
                        index += 1 if index + 1 <= len(rolls) else 0
                        break
                second, third = rolls[index + 1], rolls[index + 2]
                if second < 0 or second > 10 or third < 0 or third > 10:
                    raise ValueError("Invalid roll value")
                index += 3
            else:
                if index + 2 > len(rolls):
                    if not partial:
                        raise ValueError("Incomplete game")
                    else:
                        break
                second = rolls[index + 1]
                if second < 0 or second > 10:
                    raise ValueError("Invalid roll value")
                if first + second > 10:
                    raise ValueError("Frame sum exceeds 10")
                # Check if spare
                if first + second == 10:
                    if index + 3 > len(rolls):
                        if not partial:
                            raise ValueError("Incomplete game")
                        else:
                            break
                    third = rolls[index + 2]
                    if third < 0 or third > 10:
                        raise ValueError("Invalid roll value")
                    index += 3
                else:
                    index += 2

    # Now calculate the score
    score = 0
    roll_idx = 0
    for frame in range(10):
        if roll_idx >= len(rolls):
            break  # No more rolls to consider
        if rolls[roll_idx] == 10:  # Strike
            score += 10
            # Add next two rolls if available
            if roll_idx + 1 < len(rolls):
                score += rolls[roll_idx + 1]
            if roll_idx + 2 < len(rolls):
