def rle_pack(text):
    if not all(c.isalpha() for c in text):
        raise ValueError
    if not text:
        return ""
    result = []
    prev_char = text[0]
    count = 1
    for c in text[1:]:
        if c == prev_char:
            count += 1
        else:
            if count == 1:
                result.append(prev_char)
            else:
                result.append(str(count) + prev_char)
            prev_char = c
            count = 1
    # Add the last run
    if count == 1:
        result.append(prev_char)
    else:
        result.append(str(count) + prev_char)
    return ''.join(result)

def rle_unpack(code):
    if not all(c.isalnum() for c in code):
        raise ValueError
    i = 0
    n = len(code)
    prev_char = None
    result = []
    while i < n:
        if code[i].isdigit():
            # Parse the number
            j = i
            while j < n and code[j].isdigit():
                j += 1
            count_str = code[i:j]
            # Check leading zeros
            if len(count_str) > 1 and count_str[0] == '0':
                raise ValueError
            count = int(count_str)
            if count < 2:
                raise ValueError
            # Check there is a letter after
            if j >= n:
                raise ValueError
            current_char = code[j]
            if not current_char.isalpha():
                raise ValueError
            result.append(current_char * count)
            i = j + 1
        else:
            # Must be a letter
            current_char = code[i]
            if not current_char.isalpha():
                raise ValueError
            result.append(current_char)
            i += 1
            # Check if previous character is same
            if prev_char is not None and prev_char == current_char:
                raise ValueError
            prev_char = current_char
    # Check that consecutive items don't have same letters
