To implement `pack_flags` and `unpack_flags`, we must ensure strict boolean input validation and correct bit-level manipulation. The `pack_flags` function converts a list of booleans into a byte sequence, placing each boolean as a bit in the correct position, and zero-padding the last byte. The `unpack_flags` function reverses this process, validating the input and reconstructing the original boolean list while ensuring unused padding bits are zero.

```python
def pack_flags(flags):
    if not all(isinstance(f, bool) for f in flags):
        raise ValueError("All items must be True or False")
    n = len(flags)
    if n == 0:
        return b""
    result = bytearray()
    for b in range((n + 7) // 8):
        byte_val = 0
        for k in range(8):
            i = b * 8 + k
            if i < n and flags[i]:
                byte_val |= 1 << (7 - k)
        result.append(byte_val)
    return bytes(result)

def unpack_flags(data, n):
    if not isinstance(data, (bytes, bytearray)) or not isinstance(n, int) or n < 0:
        raise ValueError("Invalid data or n")
    if n == 0:
        if len(data) != 0:
            raise ValueError("Invalid data length")
        return []
    expected_len = (n + 7) // 8
    if len(data) != expected_len:
        raise ValueError("Invalid data length")
    result = []
    for i in range(n):
        b = i // 8
        bit_pos = 7 - (i % 8)
        if (data[b] >> bit_pos) & 1:
            result.append(True)
        else:
            result.append(False)
    # Check padding bits in the last byte
    last_byte = (n - 1) // 8
    used_bits = n % 8
    if used_bits == 0:
        used_bits = 8
    for bit in range(used_bits, 8):
        if (data[last_byte] >> (7 - bit)) & 1:
            raise ValueError("Padding bit is set")
    return result
