To solve the problem of finding the permutation at a given index and determining the rank of a permutation in lexicographic order, we use combinatorial reasoning based on factorials. For `perm_at`, we construct the permutation step by step, selecting each element by dividing the current index by the factorial of the number of remaining elements. For `perm_rank`, we calculate the rank by summing the number of permutations that precede the current one by iterating through the permutation and counting smaller elements that could precede the current one at each step.

```python
import math
from math import factorial
from functools import lru_cache

def perm_at(items, k):
    if not isinstance(items, (list, tuple)):
        raise ValueError("items must be a list or tuple")
    if not isinstance(k, int) or k < 0:
        raise ValueError("k must be a non-negative integer")
    n = len(items)
    for x in items:
        if type(x) is not int:
            raise ValueError("all items must be integers")
    unique = set(items)
    if len(unique) != n:
        raise ValueError("items must be distinct")
    try:
        fact = factorial(n)
    except:
        fact = math.factorial(n)
    if k >= fact:
        raise ValueError("k out of range")
    sorted_items = sorted(items)
    result = []
    remaining = sorted_items.copy()
    for i in range(n):
        m = n - i
        fact_m1 = factorial(m - 1)
        idx = k // fact_m1
        chosen = remaining[idx]
        result.append(chosen)
        k %= fact_m1
        remaining.remove(chosen)
    return result

def perm_rank(perm):
    if not isinstance(perm, (list, tuple)):
        raise ValueError("perm must be a list or tuple")
    for x in perm:
        if type(x) is not int:
            raise ValueError("all items must be integers")
    if len(set(perm)) != len(perm):
        raise ValueError("items must be distinct")
    sorted_perm = sorted(perm)
    rank = 0
    n = len(perm)
    for i in range(n):
        remaining = sorted_perm
        current = perm[i]
        count = 0
        for j in range(len(remaining)):
            if remaining[j] < current:
                count += 1
            elif remaining[j] == current:
                sorted_perm = remaining[:j] + remaining[j+1:]
                break
        rank += count * factorial(n - i - 1)
    return rank
