def to_base(n, base):
    if type(n) is not int:
        raise ValueError("n must be an int")
    if type(base) is not int:
        raise ValueError("base must be an int")
    if not (2 <= base <= 36):
        raise ValueError("base must be between 2 and 36")
    if n == 0:
        return "0"
    if n < 0:
        sign = "-"
        n = -n
    else:
        sign = ""
    digits = []
    while n > 0:
        remainder = n % base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        n = n // base
    return sign + ''.join(reversed(digits))

def from_base(text, base):
    if not isinstance(text, str):
        raise ValueError("text must be a str")
    if type(base) is not int:
        raise ValueError("base must be an int")
    if not (2 <= base <= 36):
        raise ValueError("base must be between 2 and 36")
    if len(text) == 0:
        raise ValueError("empty string")
    sign = 1
    start = 0
    if text[0] == '-':
        sign = -1
        start = 1
    if start == len(text):
        raise ValueError("no digits after sign")
    value = 0
    for c in text[start:]:
        digit = None
        if c.isdigit():
            digit = int(c)
        else:
            c_lower = c.lower()
            if 'a' <= c_lower <= 'z':
                digit = 10 + ord(c_lower) - ord('a')
            else:
                raise ValueError("invalid character")
        if digit >= base:
            raise ValueError("digit exceeds base")
        value = value * base + digit
    return sign * value
