To solve the problem of finding the lexicographically smallest topological order of courses, we use a modified version of Kahn's algorithm with a **min-heap** to always pick the smallest-numbered course with all prerequisites already taken. This ensures the smallest possible list in lexicographic order. The algorithm handles input validation and cycle detection efficiently, even for large input sizes.

---

```python
import heapq

def course_order(n, prereqs):
    if type(n) is not int or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(prereqs, (list, tuple)):
        raise ValueError("prereqs must be a list or tuple")

    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for p in prereqs:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError("each prerequisite must be a list or tuple of two integers")
        a, b = p
        if type(a) is not int or type(b) is not int:
            raise ValueError("prerequisite elements must be integers")
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError("prerequisite elements must be in range [0, n-1]")
        graph[a].append(b)
        in_degree[b] += 1

    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != n:
        return None
    return result
