To solve the problem of finding the minimum number of moves for a knight to reach a goal on an `n x n` chessboard with potential blocked squares, we employ **Breadth-First Search (BFS)**. BFS is ideal for finding the shortest path in an unweighted graph, where each board square is a node and each valid knight move is an edge. The algorithm explores all positions level by level, ensuring the first time the goal is reached is via the shortest path.

The knight has 8 possible moves derived from combinations of ±1 and ±2 in row and column directions. These are systematically checked for validity (within the board, not blocked, and not yet visited). To ensure correctness, input validation is performed for `n`, `start`, `goal`, and `blocked`, raising `ValueError` for invalid types or values. Special cases such as `start == goal` or blocked starting/goal positions are handled upfront.

---

```python
from collections import deque
from typing import Union, Sequence, Set, Tuple

def knight_distance(n: int, start: Sequence[int], goal: Sequence[int], blocked: Union[list, tuple, set] = ()):
    # Validate n
    if not isinstance(n, int) or not (1 <= n <= 200):
        raise ValueError("n must be an int from 1 to 200")

    # Validate start and goal
    for pos in (start, goal):
        if not isinstance(pos, (list, tuple)) or len(pos) != 2:
            raise ValueError("start and goal must be sequences of two integers")
        row, col = pos
        if not (isinstance(row, int) and not isinstance(row, bool)) or not (0 <= row < n):
            raise ValueError("start and goal coordinates must be integers in [0, n-1]")
        if not (isinstance(col, int) and not isinstance(col, bool)) or not (0 <= col < n):
            raise ValueError("start and goal coordinates must be integers in [0, n-1]")

    # Validate blocked
    if not isinstance(blocked, (list, tuple, set)):
        raise ValueError("blocked must be a list, tuple, or set")
    for square in blocked:
        if not isinstance(square, (list, tuple)) or len(square) != 2:
            raise ValueError("each blocked square must be a sequence of two integers")
        r, c = square
        if not (isinstance(r, int) and not isinstance(r, bool)) or not (0 <= r < n):
            raise ValueError("blocked coordinates must be integers in [0, n-1]")
        if not (isinstance(c, int) and not isinstance(c, bool)) or not (0 <= c < n):
            raise ValueError("blocked coordinates must be integers in [0, n-1]")

    # Convert start and goal to tuples for comparison and hashing
    start = tuple(start)
    goal = tuple(goal)

    # Check if start or goal is blocked
    if start in blocked or goal in blocked:
        return -1

    # Check if start is goal
    if start == goal:
        return 0

    # Knight's move directions
    move_dirs = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]

    # BFS initialization
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (r, c), moves = queue.popleft()

        for dr, dc in move_dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                next_pos = (nr, nc)
                if next_pos == goal:
                    return moves + 1
                if next_pos not in visited and next_pos not in blocked:
                    visited.add(next_pos)
                    queue.append((next_pos, moves + 1))

    return -1
