To determine whether a point lies inside, outside, or on the boundary of a polygon, we first check for boundary inclusion using cross products and bounding box checks. If not on the boundary, we apply the ray casting algorithm with a horizontal ray to the right. Edge crossings are identified by checking if the ray intersects the edge segment, ensuring precise integer arithmetic.

```python
def locate_points(polygon, points):
    if not isinstance(polygon, (list, tuple)) or len(polygon) < 3:
        raise ValueError("Invalid polygon")
    if not all(isinstance(v, (list, tuple)) and len(v) == 2 and all(isinstance(c, int) for c in v) for v in polygon):
        raise ValueError("Invalid polygon")
    if not all(isinstance(p, (list, tuple)) and len(p) == 2 and all(isinstance(c, int) for c in p) for p in points):
        raise ValueError("Invalid points")

    def cross(a, b, p):
        return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])

    def on_segment(a, b, p):
        if cross(a, b, p) != 0:
            return False
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    n = len(polygon)
    result = []
    for p in points:
        # Check if point is on boundary
        is_boundary = False
        for i in range(n):
            a = polygon[i]
            b = polygon[(i + 1) % n]
            if on_segment(a, b, p):
                is_boundary = True
                break
        if is_boundary:
            result.append("boundary")
            continue

        # Ray casting algorithm
        crosses = 0
        for i in range(n):
            a = polygon[i]
            b = polygon[(i + 1) % n]
            # Check if edge crosses the horizontal ray
            if (min(a[1], b[1]) < p[1] < max(a[1], b[1])):
                # Compute intersection x
                if a[1] == b[1]:
                    continue  # Should not happen as checked above
                dx = (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1]) + a[0]
                if dx >= p[0]:
                    crosses += 1
            elif (p[1] == a[1] and a[0] == p[0]) or (p[1] == b[1] and b[0] == p[0]):
                # Already checked for boundary
                pass
            elif (a[1] == p[1] and b[1] < p[1]) or (b[1] == p[1] and a[1] > p[1]) or \
                 (b[1] == p[1] and a[1] < p[1]) or (a[1] == p[1] and b[1] > p[1]):
                # One endpoint is on the ray, check if strictly to the right
                if (a[1] == p[1] and a[0] > p[0]) or (b[1] == p[1] and b[0] > p[0]):
                    crosses += 1
        result.append("inside" if crosses % 2 == 1 else "outside")
    return result
