        instr = program[pc]
        parts = instr.split(' ', 1)
        command = parts[0]

        if command == "push":
            operand = int(parts[1])
            stack.append(operand)
            pc += 1
        elif command == "pop":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
            pc += 1
        elif command == "dup":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
            pc += 1
        elif command == "swap":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif command in ["add", "sub", "mul"]:
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            b = stack.pop()
            a = stack.pop()
            if command == "add":
                stack.append(a + b)
            elif command == "sub":
                stack.append(a - b)
            elif command == "mul":
                stack.append(a * b)
            pc += 1
        elif command == "print":
            if not stack:
                raise ValueError("Stack underflow")
            output.append(stack.pop())
            pc += 1
        elif command == "jmp":
