    if not isinstance(width, int) or isinstance(width, bool):
        raise ValueError
    if width < 1:
        raise ValueError
    if not isinstance(words, (list, tuple)):
        raise ValueError
    for word in words:
        if not isinstance(word, str):
            raise ValueError
        if any(c.isspace() for c in word):
            raise ValueError
        if len(word) == 0 or len(word) > width:
            raise ValueError

    n = len(words)
    dp_memo = {}

    def dp(i):
        if i in dp_memo:
            return dp_memo[i]
        if i == n:
            return (0, [])
        min_cost = float('inf')
        best_lines = []
        current_line_length = 0
        num_words = 0
        for j in range(i + 1, n + 1):
            # Calculate line length for words[i...j-1]
            line_length = sum(len(word) for word in words[i:j]) + (j - i - 1)
            if line_length > width:
                break
            # Cost for this line if it's not the last line
            current_line_cost = (width - line_length) ** 2 if j < n else 0
            next_cost, next_lines = dp(j)
            total_cost = current_line_cost + next_cost
            # Build current line
            current_line = ' '.join(words[i:j])
            current_lines = [current_line] + next_lines
            # Update best if this is better
            if (total_cost < min_cost) or \
               (total_cost == min_cost and len(current_lines) > 0 and len(current_lines[0]) > len(best_lines[0])):
                min_cost = total_cost
                best_lines = current_lines
        # Check if we found any valid line
        if best_lines:
            dp_memo[i] = (min_cost, best_lines)
        else:
            # This shouldn't happen due to input validation
            dp_memo[i] = (0, [])
        return dp_memo[i]

    cost, lines = dp(0)
    return (cost, lines)
