def parse_ini_strict(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    sections = {}
    current_section = ""
    lines = text.splitlines()

    for line in lines:
        # Remove trailing \r if present
        if line.endswith('\r'):
            line = line[:-1]
        s = line.strip()
        if not s:
            continue
        if s[0] in (';', '#'):
            continue
        if s[0] == '[':
            # Section header
            if not s.endswith(']'):
                raise ValueError("Section header does not end with ]")
            section_name = s[1:-1].strip()
            if not section_name:
                raise ValueError("Section name cannot be empty")
            if '[' in section_name or ']' in section_name:
                raise ValueError("Section name contains invalid characters")
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            continue
        # Key-value line
        if '=' not in s:
            raise ValueError("Key-value line lacks =")
        key_part, raw_value = s.split('=', 1)
        key = key_part.strip().lower()
        if not key:
            raise ValueError("Key cannot be empty")
        # Check for duplicate key in current section
        if current_section in sections and key in sections[current_section]:
            raise ValueError(f"Duplicate key '{key}' in section '{current_section}'")
        # Process raw_value
        raw_value = raw_value.strip()
        if not raw_value:
            value = ''
        else:
            if raw_value[0] == '"':
                value, remaining = parse_quoted_value(raw_value)
                if remaining.strip():
                    # Check if remaining starts with comment
                    if not (remaining.strip()[0] in (';', '#')):
                        raise ValueError("Invalid characters after quoted value")
            else:
                value = parse_unquoted_value(raw_value)
        # Add to sections
        if current_section not in sections:
            sections[current_section] = {}
        sections[current_section][key] = value
    return sections

def parse_quoted_value(s):
    if not s.startswith('"'):
        raise ValueError("Quoted value does not start with \"")
    s = s[1:]
    value = []
    escape = False
    for i, c in enumerate(s):
        if escape:
            if c == '"':
                value.append('"')
                escape = False
            elif c == '\\':
                value.append('\\')
                escape = False
            elif c == 'n':
                value.append('\n')
                escape = False
            else:
                raise ValueError(f"Invalid escape sequence: \\{c}")
        else:
            if c == '"':
                # End of quoted string
                remaining = s[i+1:]
                return ''.join(value), remaining
            elif c == '\\':
                escape = True
            else:
                value.append(c)
    # If we reach here, the closing quote is missing
    raise ValueError("Unclosed quoted string")

def parse_unquoted_value(s):
    # Look for the first ; or # that is preceded by a whitespace
    parts = []
    in_comment = False
    i = 0
    while i < len(s):
        if s[i] in (';', '#'):
            # Check if it's preceded by a whitespace
            if i > 0 and s[i-1].isspace():
                # Split here, take the part before
                return ''.join(parts).rstrip()
        parts.append(s[i])
        i += 1
    # No comment found, return the entire string
    return ''.join(parts).strip()

