To solve this problem, we need to write two functions about integer partitions: `count_partitions` and `kth_partition`. These functions handle constraints such as maximum part size and whether parts must be distinct. The approach involves using dynamic programming for efficient computation without generating all partitions, especially for large values of `n`.

### Approach

1. **Dynamic Programming for Counting Partitions (`count_partitions`)**:
   - Use a helper function with memoization to count the number of valid partitions.
   - The helper function considers the remaining sum, maximum part size, distinct flag, and the last part used to enforce order constraints.
   - For each step, determine the valid range of parts that can be used next, considering whether parts must be distinct or not.

2. **Lexicographic Order for k-th Partition (`kth_partition`)**:
   - Construct the k-th partition by determining each part step-by-step.
   - Use the count of partitions starting with a given part to decide the next part without generating all partitions.
   - Adjust the remaining sum and update the maximum allowed part size based on the current part and constraints.

### Solution Code

```python
import sys
from functools import lru_cache

def count_partitions(n, max_part=None, distinct=False):
    if not isinstance(n, int) or not (isinstance(max_part, (int, type(None))) or max_part is None) or not isinstance(distinct, bool):
        raise ValueError("Invalid argument types")
    if n < 0 or (max_part is not None and max_part < 0):
        raise ValueError("Negative values not allowed")
    if n == 0:
        return 1 if max_part is None or max_part >= 0 else 0
    if max_part is None:
        max_part = n
    else:
        max_part = min(max_part, n)
    if max_part < 1:
        return 0

    @lru_cache(maxsize=None)
    def helper(remaining, max_part, distinct, last_part):
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        total = 0
        if last_part is None:
            start = 1
            end = max_part
        else:
            if distinct:
                end = min(last_part - 1, max_part)
            else:
                end = min(last_part, max_part)
            start = 1
        if end < start:
            return 0
        for part in range(start, end + 1):
            new_remaining = remaining - part
            if new_remaining < 0:
                continue
            if distinct:
                new_last_part = part - 1
            else:
                new_last_part = part
            total += helper(new_remaining, max_part, distinct, new_last_part)
        return total

    result = helper(n, max_part, distinct, None)
    helper.cache_clear()
    return result

def kth_partition(n, k, max_part=None, distinct=False):
    if not isinstance(n, int) or not isinstance(k, int) or not (isinstance(max_part, (int, type(None))) or max_part is None) or not isinstance(distinct, bool):
        raise ValueError("Invalid argument types")
    if n < 0 or k < 0 or (max_part is not None and max_part < 0):
        raise ValueError("Negative values not allowed")
    if n == 0:
        if k == 0:
            return ()
        else:
            raise ValueError("k out of range")
    if max_part is None:
        max_part = n
    else:
        max_part = min(max_part, n)
    if max_part < 1:
        if n == 0 and k == 0:
            return ()
        else:
            raise ValueError("No partitions possible")
    total = count_partitions(n, max_part, distinct)
    if k >= total:
        raise ValueError("k out of range")

    def find_kth(remaining, max_part, distinct, last_part, path):
        if remaining == 0:
            return tuple(path)
        for part in range(1, max_part + 1):
            if last_part is not None and (distinct and part >= last_part) or (not distinct and part > last_part):
                continue
            if distinct and part == last_part:
                continue
            if part > remaining:
                continue
            new_max = min(max_part, part - 1 if distinct else part)
            cnt = count_partitions(remaining - part, new_max, distinct)
            if cnt > k:
                continue
            k -= cnt
