def pack_flags(flags):
    if not isinstance(flags, (list, tuple)):
        raise ValueError("flags must be a list or tuple")
    for f in flags:
        if not isinstance(f, bool):
            raise ValueError("flags must contain only booleans")
    num_bytes = (len(flags) + 7) // 8
    byte_array = bytearray(num_bytes)
    for i, f in enumerate(flags):
        byte_index = i // 8
        bit_pos = 7 - (i % 8)
        if f:
            byte_array[byte_index] |= (1 << bit_pos)
    return bytes(byte_array)

def unpack_flags(data, n):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    required_bytes = (n + 7) // 8
    if len(data) != required_bytes:
        raise ValueError("data length does not match required length")
    flags = []
    for i in range(n):
        byte_index = i // 8
        bit_pos = 7 - (i % 8)
        flag = (data[byte_index] >> bit_pos) & 1
        flags.append(bool(flag))
    # Check padding bits in last byte
    if required_bytes == 0:
        return flags
    last_byte = data[-1]
    last_flag_index = n - 1
    last_byte_used_bits = (last_flag_index % 8) + 1
    if last_byte_used_bits == 8:
        padding_mask = 0
    else:
        padding_mask = (1 << (7 - last_byte_used_bits)) - 1
    if (last_byte & padding_mask) != 0:
        raise ValueError("Padding bits are not all zero")
    return flags

