def collatz_leader(limit):
    if not isinstance(limit, int) or limit < 1 or limit > 300000:
        raise ValueError

    memo = {1: 1}
    max_length = 1
    leader = 1

    for n in range(2, limit + 1):
        if n in memo:
            current_length = memo[n]
        else:
            chain = []
            current = n
            while True:
                if current in memo:
                    current_length = memo[current]
                    break
                if current == 1:
                    current_length = 1
                    break
                chain.append(current)
                if current % 2 == 0:
                    current = current // 2
                else:
                    current = 3 * current + 1
            for num in reversed(chain):
                current_length += 1
                memo[num] = current_length

        if current_length > max_length or (current_length == max_length and n < leader):
            max_length = current_length
            leader = n

    return (leader, max_length)

