def perm_at(items, k):
    if not isinstance(items, (list, tuple)):
        raise ValueError("items must be a list or tuple")
    if not all(isinstance(x, int) for x in items):
        raise ValueError("all elements in items must be integers")
    if len(set(items)) != len(items):
        raise ValueError("items must contain distinct integers")
    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError("k must be an integer")
    n = len(items)
    if n == 0:
        if k != 0:
            raise ValueError("k must be 0 for empty items")
        return []
    if k < 0 or k >= math.factorial(n):
        raise ValueError("k is out of range")
    sorted_items = sorted(items)
    result = []
    for i in range(n, 0, -1):
        fact = math.factorial(i - 1)
        index = k // fact
        result.append(sorted_items[index])
        k = k % fact
        sorted_items.pop(index)
    return result

def perm_rank(perm):
    if not isinstance(perm, (list, tuple)):
        raise ValueError("perm must be a list or tuple")
    if not all(isinstance(x, int) for x in perm):
        raise ValueError("all elements in perm must be integers")
    if len(set(perm)) != len(perm):
        raise ValueError("elements in perm must be distinct")
    n = len(perm)
    if n == 0:
        return 0
    sorted_perm = sorted(perm)
    rank = 0
    current_list = sorted_perm.copy()
    for i in range(n):
        current_element = perm[i]
        if current_element not in current_list:
            raise ValueError("perm is not a permutation of its sorted elements")
        idx = current_list.index(current_element)
        remaining = n - i - 1
        fact = math.factorial(remaining) if remaining >= 0 else 1
        rank += idx * fact
        current_list.pop(idx)
    return rank

