import heapq

def course_order(n, prereqs):
    # Validation
    if not isinstance(n, int) or n < 0:
        raise ValueError
    if n == 0:
        if len(prereqs) != 0:
            raise ValueError
        return []
    if not isinstance(prereqs, (list, tuple)):
        raise ValueError
    for pair in prereqs:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError
        a, b = pair
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError
        if isinstance(a, bool) or isinstance(b, bool):
            raise ValueError
        if a < 0 or a >= n or b < 0 or b >= n:
            raise ValueError

    # Build graph and in-degree
    adjacency = [[] for _ in range(n)]
    in_degree = [0] * n
    for a, b in prereqs:
        adjacency[a].append(b)
        in_degree[b] += 1

    # Initialize min-heap with courses having in_degree 0
    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adjacency[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != n:
        return None
    return result

