import math

def shoelace(points):
    # Validate input
    if not isinstance(points, (list, tuple)):
        raise ValueError
    if len(points) < 3:
        raise ValueError
    for point in points:
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            raise ValueError
        x, y = point
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError

    n = len(points)
    S = 0
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        S += x1 * y2 - x2 * y1

    twice_area = abs(S)
    if S > 0:
        orientation = "ccw"
    elif S < 0:
        orientation = "cw"
    else:
        orientation = "flat"

    boundary = 0
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]
        dx = abs(x2 - x1)
        dy = abs(y2 - y1)
        boundary += math.gcd(dx, dy)

    return (twice_area, boundary, orientation)

