                    counts[i] = counts[j]
                elif lengths[j] + 1 == lengths[i]:
                    counts[i] += counts[j]

    max_length = max(lengths)
    count = sum(counts[i] for i in range(n) if lengths[i] == max_length)
    return (max_length, count)

