def wrap_min_cost(words, width):
    if not isinstance(words, (list, tuple)):
        raise ValueError
    if not all(isinstance(word, str) and word and not word.isspace() and len(word) <= width for word in words):
        raise ValueError
    if not isinstance(width, int) or width < 1:
        raise ValueError

    n = len(words)
    if n == 0:
        return (0, [])

    lengths = [len(word) for word in words]

    # Precompute the prefix sums for quick calculation
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i-1] + lengths[i-1] + (1 if i > 1 else 0)

    # Initialize DP: dp[i] = (cost, best_split)
    dp = [ (float('inf'), -1) for _ in range(n + 1) ]
    dp[0] = (0, -1)

    for i in range(1, n + 1):
        for j in range(i-1, -1, -1):
            # Calculate the line length from j to i-1 (0-based)
            line_length = prefix[i] - prefix[j] - (i - j - 1)  # subtract (i-j-1) spaces
            if line_length > width:
                continue

            current_cost = dp[j][0] + (width - line_length) ** 2
            if current_cost < dp[i][0]:
                dp[i] = (current_cost, j)
            elif current_cost == dp[i][0]:
                # Prefer the split with larger j (more words in earlier lines)
                if j > dp[i][1]:
                    dp[i] = (current_cost, j)

    # Reconstruct the lines
    lines = []
    i = n
    while i > 0:
        j = dp[i][1]
        line = words[j+1:i]
        lines.append(' '.join(line))
        i = j

    lines.reverse()

    # Calculate the cost (though it's already in dp[n][0])
    cost = dp[n][0]
    return (cost, lines)

