def count_special(lo, hi, m):
    if not isinstance(lo, int) or not isinstance(hi, int) or not isinstance(m, int):
        raise ValueError("Arguments must be integers.")
    if lo < 0 or hi < 0 or m < 1 or lo > hi:
        raise ValueError("Invalid argument values.")
    if lo > hi:
        return 0

    def helper(n_str, m_val):
        from functools import lru_cache

        len_n = len(n_str)

        @lru_cache(maxsize=None)
        def dp(pos, sum_mod, last_digit, is_tight, non_zero_started):
            if pos == len_n:
                # Only valid if sum is divisible by m and non_zero_started is True (or it's zero)
                if non_zero_started:
                    return 1 if (sum_mod % m_val == 0) else 0
                else:
                    # This is the case where all digits are zero (number is 0)
                    return 1 if (sum_mod % m_val == 0) else 0

            limit = int(n_str[pos]) if is_tight else 9
            total = 0

            for d in range(0, limit + 1):
                new_is_tight = is_tight and (d == limit)
                new_non_zero_started = non_zero_started or (d != 0)

                if not non_zero_started:
                    # Still in leading zero phase
                    if d == 0:
                        # Continue leading zeros, sum remains unchanged
                        total += dp(pos + 1, sum_mod, last_digit, new_is_tight, new_non_zero_started)
                    else:
                        # Start of the number, add the digit to sum
                        total += dp(pos + 1, (sum_mod + d) % m_val, d, new_is_tight, new_non_zero_started)
                else:
                    # Already have non-zero digits, check adjacent digit constraint
                    if d == last_digit:
                        continue  # Skip if adjacent digits are equal
                    total += dp(pos + 1, (sum_mod + d) % m_val, d, new_is_tight, new_non_zero_started)

            return total

        return dp(0, 0, -1, True, False)

    if lo == 0:
        count_hi = helper(str(hi), m)
        return count_hi
    else:
        def subtract_one(n):
            s = list(str(n))
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            if i < 0:
                return -1  # n is zero
            s[i] = str(int(s[i]) - 1)
            if i == 0 and s[0] == '0' and len(s) > 1:
                s.pop(0)
            return int(''.join(s)) if any(c != '0' for c in s) else 0

        lo_minus_1 = subtract_one(lo)
        if lo_minus_1 == -1:
            return helper(str(hi), m)
        else:
            count_hi = helper(str(hi), m)
            count_lo_minus_1 = helper(str(lo_minus_1), m)
            return count_hi - count_lo_minus_1

