                prev[v] = [u]
                heapq.heappush(heap, (new_dist, v))
            elif new_dist == dist[v]:
                count[v] = (count[v] + count[u]) % MOD
                prev[v].append(u)
                heapq.heappush(heap, (new_dist, v))  # Re-add to process lex paths

