        raise ValueError
    if width < 1:
        raise ValueError
    if not isinstance(words, (list, tuple)):
        raise ValueError
    for word in words:
        if not isinstance(word, str):
            raise ValueError
        if any(c.isspace() for c in word):
            raise ValueError
        if len(word) == 0 or len(word) > width:
            raise ValueError

    n = len(words)
    dp_memo = {}

    def dp(i):
        if i in dp_memo:
            return dp_memo[i]
        if i == n:
            return (0, [])
        min_cost = float('inf')
        best_lines = []
        for j in range(i + 1, n + 1):
