            line_length = sum(len(word) for word in words[i:j]) + (j - i - 1)
            if line_length > width:
                break
            # Cost for this line if it's not the last line
            current_line_cost = (width - line_length) ** 2 if j < n else 0
            next_cost, next_lines = dp(j)
            total_cost = current_line_cost + next_cost
            # Build current line
            current_line = ' '.join(words[i:j])
            current_lines = [current_line] + next_lines
            # Check if this is better than current best
            if total_cost < min_cost:
                min_cost = total_cost
                best_lines = current_lines
            elif total_cost == min_cost:
                # Generate tie-breaking keys
                current_key = tuple(len(line.split()) for line in current_lines)
                best_key = tuple(len(line.split()) for line in best_lines)
                if current_key > best_key:
                    best_lines = current_lines
        dp_memo[i] = (min_cost, best_lines)
        return dp_memo[i]

    cost, lines = dp(0)
    return (cost, lines)
