def change_ways(amount, coins, limit=None):
    # Validate inputs
    if not isinstance(amount, int) or amount < 0:
        raise ValueError("Invalid amount")
    if not isinstance(coins, (list, tuple)):
        raise ValueError("Invalid coins")
    for c in coins:
        if not isinstance(c, int) or c < 1:
            raise ValueError("Invalid coin value")
    if len(coins) != len(set(coins)):
        raise ValueError("Coins must be distinct")
    if limit is not None:
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("Invalid limit")

    # Handle base cases
    if amount == 0:
        return 1
    if not coins:
        return 0

    # Initialize DP array
    dp = [0] * (amount + 1)
    dp[0] = 1  # Base case: one way to make 0

    for c in coins:
        if limit is None:
            # Unbounded: use as many as possible
            for i in range(c, amount + 1):
                dp[i] += dp[i - c]
        else:
