    if amount == 0:
        return 1
    if not coins:
        return 0

    # Initialize DP array
    dp = [0] * (amount + 1)
    dp[0] = 1  # Base case: one way to make 0

    for c in coins:
        if limit is None:
            # Unbounded: use as many as possible
            for i in range(c, amount + 1):
                dp[i] += dp[i - c]
        else:
            # Bounded: use up to 'limit' times
            # Iterate in reverse to prevent using the same coin multiple times in the same step
            for i in range(amount, c - 1, -1):
                # For each possible count of current coin (from 1 to limit)
                max_use = min(limit, i // c)
                for k in range(1, max_use + 1):
                    if i >= k * c:
                        dp[i] += dp[i - k * c]

    return dp[amount]

