def locate_points(polygon, points):
    if not isinstance(polygon, (list, tuple)) or len(polygon) < 3:
        raise ValueError
    for vertex in polygon:
        if not (isinstance(vertex, (list, tuple)) and len(vertex) == 2 and isinstance(vertex[0], int) and isinstance(vertex[1], int)):
            raise ValueError
    if not isinstance(points, (list, tuple)):
        raise ValueError
    for point in points:
        if not (isinstance(point, (list, tuple)) and len(point) == 2 and isinstance(point[0], int) and isinstance(point[1], int)):
            raise ValueError

    n = len(polygon)
    result = []

    for p in points:
        px, py = p
        on_boundary = False

        for i in range(n):
            a = polygon[i]
            b = polygon[(i + 1) % n]
            ax, ay = a
            bx, by = b

            cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
            if cross != 0:
                continue

            min_x = min(ax, bx)
            max_x = max(ax, bx)
            min_y = min(ay, by)
            max_y = max(ay, by)

            if (min_x <= px <= max_x) and (min_y <= py <= max_y):
                on_boundary = True
                break

        if on_boundary:
            result.append("boundary")
            continue

        count = 0

        for i in range(n):
            a = polygon[i]
            b = polygon[(i + 1) % n]
            ax, ay = a
            bx, by = b

            if ay == by:
                continue

            if (ay < py and by >= py) or (by < py and ay >= py):
                # Calculate intersection x-coordinate using integer arithmetic
                numerator = (py - ay) * (bx - ax)
                denominator = by - ay
                px_diff = px - ax

                # Check if ax + numerator/denominator > px
                # This is equivalent to (numerator > px_diff * denominator) if denominator > 0
                if denominator > 0:
                    if numerator > px_diff * denominator:
                        count += 1
                else:  # denominator < 0
                    if numerator < px_diff * denominator:
                        count += 1

        result.append("inside" if count % 2 == 1 else "outside")

    return result

