    n = len(program)

    while 0 <= pc < n:
        instr = program[pc]
        parts = instr.split()
        op = parts[0]

        if op == 'push':
            stack.append(int(parts[1]))
            pc += 1

        elif op == 'pop':
            if len(stack) < 1:
                raise ValueError("Not enough elements to pop.")
            stack.pop()
            pc += 1

        elif op == 'dup':
            if len(stack) < 1:
                raise ValueError("Not enough elements to duplicate.")
            stack.append(stack[-1])
            pc += 1

        elif op == 'swap':
            if len(stack) < 2:
                raise ValueError("Not enough elements to swap.")
            a, b = stack.pop(), stack.pop()
            stack.append(a)
            stack.append(b)
            pc += 1

        elif op in ['add', 'sub', 'mul']:
            if len(stack) < 2:
                raise ValueError(f"Not enough elements for {op}.")
            b, a = stack.pop(), stack.pop()
            if op == 'add':
                stack.append(a + b)
            elif op == 'sub':
                stack.append(a - b)
            elif op == 'mul':
                stack.append(a * b)
            pc += 1

        elif op == 'print':
            if len(stack) < 1:
                raise ValueError("Not enough elements to print.")
            output.append(stack.pop())
            pc += 1

        elif op == 'jz':
            target = int(parts[1])
            if len(stack) < 1:
                raise ValueError("Not enough elements for jz.")
            val = stack.pop()
            if val == 0:
                pc = target
            else:
                pc += 1

        elif op == 'jmp':
            target = int(parts[1])
            pc = target

        elif op == 'halt':
            break

        else:
            pc += 1

    return output
